const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');

// A simple stack-based parser to track nesting of section tags or other divs
const lines = html.split('\n');
let openTags = [];
let targetLine = -1;

for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Check for target
    if (line.includes('id="page-agen-training"')) {
        targetLine = i + 1;
        console.log(`Found target at line ${targetLine}:`, line.trim());
        console.log('Open tags stack at this point:', openTags.map(t => `${t.tag} (line ${t.line})`));
    }

    // Parse tags in line (simple regex, not full HTML parser but good for structure)
    const tagRegex = /<\/?([a-zA-Z0-9:-]+)(?:\s+[^>]*?)?>/g;
    let match;
    while ((match = tagRegex.exec(line)) !== null) {
        const fullTag = match[0];
        const tagName = match[1].toLowerCase();

        if (fullTag.startsWith('</')) {
            // Closing tag
            if (openTags.length > 0 && openTags[openTags.length - 1].tag === tagName) {
                openTags.pop();
            } else {
                // Mismatch or pop anyway
                // Search backwards for matching tag
                const idx = openTags.map(t => t.tag).lastIndexOf(tagName);
                if (idx !== -1) {
                    openTags.splice(idx);
                }
            }
        } else if (!fullTag.endsWith('/>') && !['img', 'br', 'hr', 'input', 'meta', 'link'].includes(tagName)) {
            // Opening tag
            openTags.push({ tag: tagName, line: i + 1 });
        }
    }
}

