window.loadModuleDetail = function(moduleId) {
    try {
        const moduleData = window.modules.find(m => m.id === moduleId);
        if (!moduleData) {
            console.error("Modul tidak ditemukan:", moduleId);
            return;
        }

        window.currentActiveModuleId = moduleId;

        // Setup Tabs Event Listener
        window.setupMaterialTabs();

        // Elemen Kontainer
        const titleEl = document.getElementById('player-title');
        const categoryEl = document.getElementById('player-category');
        const articleEl = document.getElementById('player-article-content');
        const videoFrame = document.getElementById('player-video-frame');
        const pdfNameEl = document.getElementById('player-pdf-name');
        const summaryEl = document.getElementById('player-summary-text');

        // Isi Data Utama
        if (titleEl) titleEl.textContent = moduleData.title || 'Materi Belajar';
        if (categoryEl) categoryEl.textContent = moduleData.cat || 'Asuransi Umum';
        if (articleEl) {
            let artContent = moduleData.article || moduleData.content || "";
            if (!artContent || artContent.trim() === "") {
                articleEl.innerHTML = '<p>Tidak ada artikel tertulis untuk modul ini.</p>';
            } else {
                articleEl.innerHTML = artContent.replace(/\n/g, "<br>");
            }
        }

        const videoWrapper = document.getElementById('tab-video');
        let rawVideo = moduleData.video || moduleData.videoUrl || '';
        if (rawVideo && rawVideo.trim() !== "") {
            let embedUrl = rawVideo;
            if (rawVideo.includes("youtube.com/watch?v=")) {
                const vidId = rawVideo.split("v=")[1].split("&")[0];
                embedUrl = `https://www.youtube.com/embed/${vidId}`;
            } else if (rawVideo.includes("youtu.be/")) {
                const vidId = rawVideo.split("youtu.be/")[1].split("?")[0];
                embedUrl = `https://www.youtube.com/embed/${vidId}`;
            }
            if (videoWrapper) {
                videoWrapper.innerHTML = `
                    <div class="video-player-wrapper">
                      <iframe id="player-video-frame" width="100%" height="400" src="${embedUrl}" frameborder="0" allowfullscreen></iframe>
                      <p class="video-caption">Gunakan video pemaparan ini untuk menyelaraskan teori dengan praktek penjualan di lapangan.</p>
                    </div>
                `;
            }
        } else {
            if (videoWrapper) {
                videoWrapper.innerHTML = `
                    <div style="padding: 40px 20px; text-align: center; color: var(--text-muted); background: #f8fafc; border-radius: 8px; border: 1px dashed #cbd5e1; margin-top: 20px;">
                        Belum ada video untuk materi ini.
                    </div>
                `;
            }
        }
        // Logika Tab PDF (Google Drive External Link)
        const pdfTabContainer = document.getElementById('tab-pdf');
        if (pdfTabContainer) {
            const pdfUrl = moduleData.pdfLink || '#';
            const disableAttr = moduleData.pdfLink ? '' : 'pointer-events: none; opacity: 0.6;';
            const titleText = moduleData.pdfLink ? 'Materi PDF Tersedia' : 'Materi PDF Tidak Tersedia';
            const descText = moduleData.pdfLink 
                ? 'Klik tombol di bawah ini untuk membuka dan mengunduh materi PDF resmi melalui Google Drive dengan aman.' 
                : 'Belum ada tautan materi PDF yang diunggah oleh Trainer untuk modul ini.';

            pdfTabContainer.innerHTML = `
                <div class="pdf-card-box" style="text-align: center; padding: 40px 20px; background: #f8fafc; border: 1px dashed #cbd5e1; border-radius: 8px;">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#2563eb" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width: 48px; height: 48px; margin-bottom: 16px;">
                        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
                        <polyline points="14 2 14 8 20 8"></polyline>
                        <line x1="16" y1="13" x2="8" y2="13"></line>
                        <line x1="16" y1="17" x2="8" y2="17"></line>
                        <polyline points="10 9 9 9 8 9"></polyline>
                    </svg>
                    <h3 style="margin-bottom: 8px; color: var(--text-dark);">${titleText}</h3>
                    <p style="color: var(--text-muted); font-size: 14px; margin-bottom: 24px; max-width: 400px; margin-left: auto; margin-right: auto;">${descText}</p>
                    <a href="${pdfUrl}" target="_blank" rel="noopener noreferrer" style="display: inline-block; padding: 12px 24px; background-color: #2563eb; color: #fff; text-decoration: none; border-radius: 6px; font-weight: 600; transition: background-color 0.2s; ${disableAttr}" onmouseover="this.style.backgroundColor='#1d4ed8'" onmouseout="this.style.backgroundColor='#2563eb'">
                        Buka Materi di Google Drive
                    </a>
                </div>
            `;
        }

        if (summaryEl) summaryEl.innerHTML = moduleData.desc || 'Tidak ada ringkasan.';

        // Logika Tab Kuis
        const tabs = document.querySelectorAll('.player-tab-btn');
        const quizTabBtn = Array.from(tabs).find(el => el.textContent.includes('Kuis'));

        if (moduleData.wajibKuis) {
            if (quizTabBtn) quizTabBtn.style.display = 'inline-block';
            if (typeof window.renderAgenMaterialQuiz === 'function') {
                window.renderAgenMaterialQuiz(moduleId);
            }
        } else {
            if (quizTabBtn) quizTabBtn.style.display = 'none';
        }

        // Default: Klik tab pertama (Artikel) agar otomatis terbuka
        if (tabs.length > 0) {
            tabs[0].click();
        }

    } catch (e) {
        console.error("Gagal memuat detail modul:", e);
    }
};

