window.saveTrainerMaterial = function() {
    const title = document.getElementById("trn-mat-title").value;
    const cat = document.getElementById("trn-mat-cat").value;
    const levelEl = document.getElementById("trn-mat-level");
    const level = levelEl ? levelEl.value : "Basic";

    const descEl = document.getElementById("trn-mat-desc");
    const desc = descEl ? descEl.value : "";

    const articleEl = document.getElementById("trn-mat-article");
    const article = articleEl ? articleEl.value : "";

    const pdfEl = document.getElementById("trn-mat-pdf");
    let pdf = "";
    if (pdfEl) {
        if (pdfEl.files && pdfEl.files.length > 0) {
            pdf = pdfEl.files[0].name;
        } else {
            pdf = pdfEl.value.split('\\').pop().split('/').pop();
        }
    }

    const videoEl = document.getElementById("trn-mat-video");
    const video = videoEl ? videoEl.value : "";

    if (!title) {
        alert("Judul Modul wajib diisi.");
        return;
    }

    let wajibKuis = false;
    let soalKuis = [];
    const hasQuizEl = document.getElementById("trn-mat-has-quiz");
    if (hasQuizEl && hasQuizEl.checked) {
        wajibKuis = true;
        const items = document.querySelectorAll("#new-mod-quiz-questions-list .quiz-question-item");
        items.forEach(item => {
            const q = item.querySelector(".trn-mat-q-q").value;
            const a = item.querySelector(".trn-mat-q-a").value;
            const b = item.querySelector(".trn-mat-q-b").value;
            const c = item.querySelector(".trn-mat-q-c").value;
            const d = item.querySelector(".trn-mat-q-d").value;
            const correct = item.querySelector(".trn-mat-q-correct").value;
            if (q) {
                soalKuis.push({ q, a, b, c, d, correct });
            }
        });
    }

    let newMat = {
        id: "MOD-" + Math.floor(Math.random() * 100000),
        title: title,
        judul: title, // Untuk skema baru
        cat: cat,
        level: level,
        desc: desc,
        article: article,
        pdf: pdf,
        video: video,
        quizCount: soalKuis.length,
        wajibKuis: wajibKuis,
        soalKuis: soalKuis
    };

    window.modules.unshift(newMat);
    window.saveDataToStorage();

    alert("Modul Berhasil Disimpan!");
    hideCreateMaterialModal();
    renderTrainerMaterials();
};

window.renderTrainerMaterials = function() {
    const tbody = document.getElementById('trainer-material-rows');
    if (!tbody) return;

    let materials = JSON.parse(localStorage.getItem('pa_materials')) || [];
    if (materials.length === 0) {
        materials = [
            { id: "mat-1", title: "Asuransi Jiwa Dasar", cat: "Dasar Asuransi", quizCount: 5 },
            { id: "mat-2", title: "Asuransi Properti Komersial", cat: "Asuransi Properti", quizCount: 10 }
        ];
        localStorage.setItem('pa_materials', JSON.stringify(materials));
    }

    tbody.innerHTML = "";
    materials.forEach(m => {
        if (!m) return;

        const judulTeks = m.title || m.judul || 'Tanpa Judul';
        const kategoriTeks = m.kategori || m.kategoriMateri || m.cat || 'Tanpa Kategori';
        const jumlahKuis = (m.kuis && Array.isArray(m.kuis)) ? m.kuis.length : (m.quizCount || 0);

        tbody.innerHTML += `
            <tr>
                <td><strong>${judulTeks}</strong></td>
                <td>${kategoriTeks} <br><small style="color:var(--text-muted); font-weight:600;">(${m.level || 'Basic'})</small></td>
                <td>${jumlahKuis} Soal</td>
                <td>
                    <button class="btn-secondary" style="padding:4px 8px; font-size:11px;" onclick="alert('Demo: Hapus modul ini')">Hapus</button>
                </td>
            </tr>
        `;
    });
};

